CREATE TABLE hub_campaign_plans(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),name TEXT NOT NULL,platform TEXT NOT NULL,objective TEXT NOT NULL,currency TEXT,budget_minor INTEGER,budget_basis TEXT NOT NULL CHECK(budget_basis IN ('total','daily')),start_date TEXT,end_date TEXT,countries TEXT NOT NULL DEFAULT '[]',audience TEXT NOT NULL DEFAULT '',brief TEXT NOT NULL DEFAULT '',destination TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('draft','ready','archived')),version INTEGER NOT NULL DEFAULT 1,client_key TEXT NOT NULL,payload_hash TEXT NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,client_key));
CREATE INDEX hub_campaign_brand ON hub_campaign_plans(workspace_id,brand_id,status);
CREATE TABLE hub_campaign_posts(campaign_id TEXT NOT NULL REFERENCES hub_campaign_plans(id),post_id TEXT NOT NULL REFERENCES hub_posts(id),PRIMARY KEY(campaign_id,post_id));
CREATE TABLE hub_campaign_edit_guards(id TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));
